const DEFAULT_CHECK_INTERVAL_MS = 100;

export const waitForCanvasStability = (
  container: HTMLElement,
  stableFrames = 3,
  maxWaitMs = 5000,
  checkIntervalMs = DEFAULT_CHECK_INTERVAL_MS,
): Promise<void> =>
  new Promise((resolve) => {
    const canvases = container.querySelectorAll('canvas');
    if (canvases.length === 0) {
      resolve();
      return;
    }

    let consecutiveStable = 0;
    let previousSnapshots: string[] = [];
    const startTime = Date.now();

    const getSnapshots = (): string[] =>
      Array.from(canvases).map((canvas) => {
        try {
          return canvas.toDataURL('image/png');
        } catch {
          return '';
        }
      });

    const finish = () => {
      clearInterval(intervalId);
      clearTimeout(timeoutId);
      resolve();
    };

    const check = () => {
      if (Date.now() - startTime > maxWaitMs) {
        finish();
        return;
      }

      const current = getSnapshots();
      const allMatch =
        previousSnapshots.length === current.length &&
        current.every((snap, i) => snap === previousSnapshots[i]);

      if (allMatch) {
        consecutiveStable++;
      } else {
        consecutiveStable = 0;
      }

      previousSnapshots = current;

      if (consecutiveStable >= stableFrames) {
        finish();
      }
    };

    previousSnapshots = getSnapshots();
    const intervalId = setInterval(check, checkIntervalMs);
    const timeoutId = setTimeout(finish, maxWaitMs);
  });
